package app.dayflow.markdown;import android.content.Context;import org.json.*;import java.io.*;import android.util.AtomicFile;
final class NoteDrafts {static boolean exists(Context c,String id){return new File(new File(c.getFilesDir(),"drafts"),id+".md").isFile();}static String read(Context c,String id)throws Exception{java.util.UUID.fromString(id);try(InputStream in=new FileInputStream(new File(new File(c.getFilesDir(),"drafts"),id+".md"))){return MarkdownFiles.read(in);}}static void queue(Context c,JSONObject r,java.util.function.Consumer<String> result){try{java.io.File dir=new File(c.getFilesDir(),"drafts");dir.mkdirs();AtomicFile file=new AtomicFile(new File(dir,r.optString("id")+".md"));FileOutputStream out=null;try{out=file.startWrite();Writer writer=new OutputStreamWriter(out,java.nio.charset.StandardCharsets.UTF_8);writer.write(r.optString("content"));writer.flush();file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}result.accept("草稿已留在插件本机");}catch(Exception e){result.accept("草稿未保存，可返回主应用恢复原文");}}static void clear(Context c,String id){new AtomicFile(new File(new File(c.getFilesDir(),"drafts"),id+".md")).delete();}}
